const idb = () => new Promise((res, rej) => { const r = indexedDB.open('bs-practice', 1); r.onupgradeneeded = () => r.result.createObjectStore('packs', { keyPath: 'name' }); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); });
